# Creates the 6 new Out BIT standard alias devices (SDSID 100..105) with the native AliasDevice writer (CRC regenerated by ToXml).
. "$PSScriptRoot\sds-lib.ps1" | Out-Null
$src='C:\Users\user\source\repos\MEN001_Dyno_v2\MEN001_Dyno\Safety_Dyno\TwinSafeGroup1\Alias Devices\PLC_IO\OUT_Estop_OK.sds'
$outDir=$args[0]
[IO.Directory]::CreateDirectory($outDir)|Out-Null
$map=[ordered]@{OUT_STS_RND=100;OUT_STS_RUN=101;OUT_STS_EMG=102;OUT_STS_CFG=103;OUT_STS_COVER_LOCKED=104;OUT_STS_FAULT=105}
foreach($k in $map.Keys){
 $xml=New-SdsXml $src $map[$k]
 [IO.File]::WriteAllText((Join-Path $outDir ($k+'.sds')),$xml,(New-Object Text.UTF8Encoding($true)))
 Write-Output "$k $($map[$k]) len $($xml.Length)"
}
